import React from 'react';

const products = [
  {
    id: 1,
    name: 'Handmade Wooden Elephant',
    category: 'Wood Carving',
    price: 2500,
  },
  {
    id: 2,
    name: 'Traditional Batik Design',
    category: 'Batik',
    price: 3500,
  },
  {
    id: 3,
    name: 'Handmade Clay Pot',
    category: 'Pottery',
    price: 1800,
  },
  {
    id: 4,
    name: 'Traditional Handloom Bag',
    category: 'Handloom',
    price: 2200,
  },
];

function ProductCatalog() {
  return (
    <div style={{ padding: '30px' }}>
      <h1>Explore Sri Lankan Crafts</h1>
      <p>Discover unique products made by local artisans.</p>

      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))',
          gap: '20px',
        }}
      >
        {products.map((product) => (
          <div
            key={product.id}
            style={{
              border: '1px solid #ddd',
              borderRadius: '10px',
              padding: '20px',
              background: '#fff',
            }}
          >
            <h3>{product.name}</h3>
            <p>{product.category}</p>
            <strong>
              LKR {product.price.toLocaleString()}
            </strong>
          </div>
        ))}
      </div>
    </div>
  );
}

export default ProductCatalog;
